input:
{
  "title": "Jumia Price Intelligence Input",
  "type": "object",
  "schemaVersion": 1,
  "properties": {
    "searchKeyword": {
      "title": "Search keyword",
      "type": "string",
      "description": "Product search term, e.g. 'laptop', 'samsung phone', 'nike shoes'.",
      "editor": "textfield",
      "example": "laptop",
      "prefill": "laptop"
    },
    "countries": {
      "title": "Countries to scrape",
      "type": "array",
      "description": "List of Jumia country codes to scrape. Live stores: ng (Nigeria), ke (Kenya), eg (Egypt), gh (Ghana), ug (Uganda), ci (Côte d'Ivoire), ma (Morocco), sn (Senegal). Jumia closed tn, dz and tz; those are skipped.",
      "editor": "stringList",
      "default": [
        "ng"
      ],
      "example": [
        "ng",
        "ke",
        "gh"
      ]
    },
    "maxResults": {
      "title": "Max results per country",
      "type": "integer",
      "description": "Maximum number of products to return per country. Jumia hard-limits search results to 2,000 per query.",
      "editor": "number",
      "default": 100,
      "minimum": 1,
      "maximum": 2000
    },
    "scrapeDetails": {
      "title": "Scrape product detail pages",
      "type": "boolean",
      "description": "When enabled, the actor visits each product page to extract full specifications, description, images, and seller info. Slower and more expensive — disable for bulk price monitoring.",
      "editor": "checkbox",
      "default": false
    },
    "minPrice": {
      "title": "Minimum price filter",
      "type": "number",
      "description": "Only return products at or above this price (in local currency). Leave blank to disable.",
      "editor": "number"
    },
    "maxPrice": {
      "title": "Maximum price filter",
      "type": "number",
      "description": "Only return products at or below this price (in local currency). Leave blank to disable.",
      "editor": "number"
    },
    "proxyConfiguration": {
      "title": "Proxy configuration",
      "type": "object",
      "description": "Apify Proxy configuration. Residential proxies are required for reliable Jumia access. If proxy country is omitted, the actor automatically uses the first selected country.",
      "editor": "proxy",
      "default": {
        "useApifyProxy": true,
        "apifyProxyGroups": [
          "RESIDENTIAL"
        ]
      }
    }
  },
  "required": [
    "searchKeyword"
  ]
}
